 static JSONObject packet()throws Exception{return new JSONObject().put("result",new JSONObject().put("status",new JSONObject().put("code",0)).put("data",new JSONArray().put(new JSONObject().put("id","source-1").put("title","建设银行合同公告报道").put("intro","601939合同摘要").put("url","https://finance.sina.com.cn/test/article.shtml").put("ctime",NOW.getEpochSecond()).put("keywords","银行,合同"))));}
