 static void onUi(Work work)throws Exception{if(Looper.myLooper()==Looper.getMainLooper()){work.run();return;}CountDownLatch done=new CountDownLatch(1);AtomicReference<Throwable> failure=new AtomicReference<>();new Handler(Looper.getMainLooper()).post(()->{try{work.run();}catch(Throwable e){failure.set(e);}finally{done.countDown();}});need(done.await(8,TimeUnit.SECONDS),"bounded UI operation");if(failure.get()!=null)throw new AssertionError(failure.get());}
 static void waitUi(BooleanSupplier condition)throws Exception{need(Looper.myLooper()!=Looper.getMainLooper(),"ui checks run on instrumentation worker");long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);AtomicBoolean ready=new AtomicBoolean();while(System.nanoTime()<deadline){onUi(()->ready.set(condition.getAsBoolean()));if(ready.get())return;Thread.sleep(20);}throw new AssertionError("News UI async deadline");}
