 public static JSONObject real(Path directory)throws Exception{
  Files.createDirectory(directory);JSONObject receipt=new JSONObject().put("startedAt",NewsModel.time(Instant.now())).put("boundary","one market batch (2 columns x 1 page) and at most one allowlisted article; no retry/auth bypass").put("device",false);
  try(NewsFeed source=new NewsFeed()){JSONObject s=source.fetch(NewsModel.query("market",1,1,"",""),null);Files.write(directory.resolve("snapshot.json"),s.toString(2).getBytes(StandardCharsets.UTF_8));for(int i=0;i<source.rawResponses.size();i++)Files.write(directory.resolve(String.format(Locale.ROOT,"list-%02d.raw",i+1)),source.rawResponses.get(i));Files.write(directory.resolve("list-receipts.json"),new JSONArray(source.observations).toString(2).getBytes(StandardCharsets.UTF_8));receipt.put("listComplete",s.getBoolean("complete")).put("itemCount",s.getJSONArray("items").length()).put("listError",s.getString("error"));JSONObject target=null;if(s.getBoolean("complete"))for(int i=0;i<s.getJSONArray("items").length();i++){JSONObject row=s.getJSONArray("items").getJSONObject(i);try{NewsModel.url(row.getString("link"),true);target=row;break;}catch(Exception ignored){}}if(target!=null){JSONObject a=source.article(target,null);Files.write(directory.resolve("article.json"),new JSONObject().put("item",target).put("article",a).toString(2).getBytes(StandardCharsets.UTF_8));for(int i=0;i<source.rawResponses.size();i++)Files.write(directory.resolve(String.format(Locale.ROOT,"article-%02d.raw",i+1)),source.rawResponses.get(i));Files.write(directory.resolve("article-receipts.json"),new JSONArray(source.observations).toString(2).getBytes(StandardCharsets.UTF_8));receipt.put("articleStatus",a.getString("status")).put("articleMessage",a.getString("message")).put("articleUrl",target.getString("link"));}else receipt.put("articleStatus","not-attempted-no-supported-item");}
  catch(Exception e){receipt.put("exception",e.getMessage()==null?e.getClass().getSimpleName():e.getMessage());}receipt.put("finishedAt",NewsModel.time(Instant.now()));Files.write(directory.resolve("receipt.json"),receipt.toString(2).getBytes(StandardCharsets.UTF_8));return receipt;
 }
